require('dotenv').config(); const express=require('express'); const cors=require('cors'); const mysql=require('mysql2/promise'); const app=express(); app.use(cors()); app.use(express.json()); const pool=mysql.createPool({host:process.env.DB_HOST,user:process.env.DB_USER,password:process.env.DB_PASSWORD,database:process.env.DB_NAME,connectionLimit:10}); app.get('/api/students',async(req,res)=>{try{const [rows]=await pool.query('SELECT id,name,course FROM students ORDER BY id');res.json(rows);}catch(e){res.status(500).json({error:e.message});}}); app.listen(process.env.PORT||3000,()=>console.log('API running on port '+(process.env.PORT||3000)));
